import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.CfX5xiXd.js";var i=JSON.parse(`{"title":"Guides","description":"","frontmatter":{},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md","lastUpdated":1784264965000}`),a={name:`guides/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to “Guides”">​</a></h1><p>MangaReader content and tracker extensions connect the app to external services. The repository does not host comics. Theme extension packages are not supported.</p><h2 id="browse-extensions" tabindex="-1">Browse extensions <a class="header-anchor" href="#browse-extensions" aria-label="Permalink to “Browse extensions”">​</a></h2><p>The <a href="/extensions/extension-list">Extension List</a> presents:</p><ol><li><strong>Package identity</strong> — name, version, kind, language, and content rating.</li><li><strong>Compatibility</strong> — supported MangaReader API version, features, and known limitations.</li><li><strong>Package information</strong> — compressed size, contributors, and repository.</li><li><strong>Source and provenance</strong> — package source, upstream snapshot, license, and revision links.</li></ol><div class="tip custom-block"><p class="custom-block-title">Keep packages current</p><p>Refresh a repository to check for newer manifest versions, then use Update for the extensions you want to replace.</p></div><h2 id="custom-catalogs" tabindex="-1">Custom catalogs <a class="header-anchor" href="#custom-catalogs" aria-label="Permalink to “Custom catalogs”">​</a></h2><p>The catalog browser accepts either a full <code>catalog.json</code> URL or the directory containing it. A compatible catalog must:</p><ul><li>be served over HTTP or HTTPS without embedded credentials;</li><li>expose a JSON object with a <code>sources</code> array;</li><li>give every source a unique, non-empty <code>id</code>;</li><li>contain content or tracker extensions (<code>kind: &quot;content&quot;</code> or <code>kind: &quot;tracker&quot;</code>; an omitted kind defaults to content);</li><li>publish package and icon paths relative to its repository URL; and</li><li>permit browser access with appropriate cross-origin response headers.</li></ul><p>Custom catalog URLs are saved in local browser storage. They are never synchronized to an account because this website has no sign-in or backend. Shared catalog links include the custom URLs required to reproduce the view.</p><p>To remove a custom catalog, open <strong>Repositories</strong> on the Extension List and select the × button next to it.</p><h2 id="content-ratings" tabindex="-1">Content ratings <a class="header-anchor" href="#content-ratings" aria-label="Permalink to “Content ratings”">​</a></h2><table tabindex="0"><thead><tr><th>Rating</th><th>Intended use</th></tr></thead><tbody><tr><td>Safe</td><td>General-audience material.</td></tr><tr><td>Mature</td><td>Material that may include stronger themes or imagery.</td></tr><tr><td>Adult</td><td>Explicit material intended only for adults where lawful.</td></tr><tr><td>Unknown</td><td>The publisher did not provide a recognized rating.</td></tr></tbody></table><p>The Extension List begins with <strong>Safe</strong> included when opened without a shared state. Click a filter once to include it, twice to exclude it, and a third time to clear it. Clearing all rating filters shows every rating.</p><h2 id="troubleshooting-catalogs" tabindex="-1">Troubleshooting catalogs <a class="header-anchor" href="#troubleshooting-catalogs" aria-label="Permalink to “Troubleshooting catalogs”">​</a></h2><p>If a custom catalog does not load:</p><ul><li>confirm that its address resolves to <code>catalog.json</code>;</li><li>open the JSON address directly and check for an HTTP error;</li><li>make sure the catalog server allows cross-origin browser requests;</li><li>check that <code>sources</code> is an array with no duplicate IDs; and</li><li>remove credentials, fragments, and unrelated JSON filenames from the URL.</li></ul>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};